(async()=>{
'use strict';
const button=document.getElementById('test-pay'),status=document.getElementById('checkout-status'),content=document.getElementById('checkout-plan'),consent=document.getElementById('test-consent'),planId=new URLSearchParams(location.search).get('plan');
async function api(path,body){const r=await fetch('/api/payments/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||'Test checkout unavailable.');return data;}
try{const config=await api('config'),plan=Object.hasOwn(config.plans,planId)?config.plans[planId]:null;if(!plan){status.textContent='Choose Inquiry Essential, Professional or Advanced from the plans page. Institutional plans require a proposal.';return;}const heading=document.createElement('h2');heading.textContent=plan.name;const details=document.createElement('p');details.textContent='Test base amount: '+new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(plan.amount/100)+' · '+plan.months+' months · Up to '+plan.users+' users. Planned software licence for one authorised proceeding, followed by three months read-only.';content.append(heading,details);const scope=document.createElement('p');scope.textContent=plan.scope||'Planned paid scope is subject to the written licence.';content.append(scope);if(Array.isArray(plan.includes)){const list=document.createElement('ul');for(const feature of plan.includes){const row=document.createElement('li');row.textContent=feature;list.append(row)}content.append(list)}const licence=document.createElement('p');licence.textContent='Licence: one authorised proceeding; '+(plan.readOnlyMonths||3)+' additional months read-only. Prices exclude applicable GST. User accounts do not replace legally required Committee participation. Upgrades do not automatically restart the existing term. Additional users, extensions and activation follow agreed terms.';content.append(licence);
if(!config.configured){status.textContent='Test checkout has not been enabled yet. No payment can be taken.';return;}button.textContent='Open Razorpay test checkout';consent.addEventListener('change',()=>button.disabled=!consent.checked);
button.addEventListener('click',async()=>{button.disabled=true;status.textContent='Creating a test order…';try{const order=await api('order',{plan:planId,testConsent:consent.checked});if(!window.Razorpay)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=resolve;script.onerror=()=>reject(Error('Could not load Razorpay test checkout.'));document.head.append(script)});let verifying=false,completed=false;const checkout=new window.Razorpay({key:order.keyId,order_id:order.orderId,amount:order.amount,currency:'INR',name:'The Cosmic Energizers',description:order.name+' — staging test only',theme:{color:'#102039'},handler:async response=>{if(verifying||completed)return;verifying=true;status.textContent='Verifying test payment…';try{const result=await api('verify',{context:order.context,orderId:response.razorpay_order_id,paymentId:response.razorpay_payment_id,signature:response.razorpay_signature});completed=true;status.textContent=result.message}catch(e){status.textContent=e.message}finally{verifying=false;button.disabled=completed||!consent.checked}},modal:{ondismiss:()=>{if(verifying||completed)return;status.textContent='Test checkout closed. No service has been activated.';button.disabled=!consent.checked}}});checkout.on('payment.failed',()=>{status.textContent='The test payment failed. You can retry. No service has been activated.';button.disabled=!consent.checked});status.textContent='Complete the simulated payment in Razorpay Test Mode.';checkout.open();}catch(e){status.textContent=e.message;button.disabled=!consent.checked}});
}catch(e){status.textContent=e.message}
})();
